import 'dart:async'; import 'package:flutter/material.dart'; import '../core/theme.dart'; import '../data/sample_anime.dart'; import '../models/anime.dart'; import '../services/anime_api.dart'; import '../widgets/anime_widgets.dart';
class DiscoverPage extends StatefulWidget{const DiscoverPage({super.key,required this.onOpen});final ValueChanged<Anime> onOpen;@override State<DiscoverPage> createState()=>_DiscoverPageState();}
class _DiscoverPageState extends State<DiscoverPage>{final controller=TextEditingController();Timer? debounce;List<Anime> results=sampleAnime;bool loading=false;String? note;
void search(String s){debounce?.cancel();if(s.trim().isEmpty){setState(()=>results=sampleAnime);return;}debounce=Timer(const Duration(milliseconds:400),()async{setState(()=>loading=true);try{final r=await AnimeApi.search(s);if(mounted)setState(()=>{results=r,loading=false,note=null});}catch(_){if(mounted)setState(()=>{results=sampleAnime.where((a)=>a.title.toLowerCase().contains(s.toLowerCase())).toList(),loading=false,note='API unavailable — showing suggestions.'});}});}
@override void dispose(){debounce?.cancel();controller.dispose();super.dispose();}
@override Widget build(BuildContext c)=>SafeArea(child:Column(children:[const Padding(padding:EdgeInsets.all(18),child:Align(alignment:Alignment.centerLeft,child:Text('Discover',style:TextStyle(fontSize:28,fontWeight:FontWeight.w900)))),Padding(padding:const EdgeInsets.symmetric(horizontal:16),child:TextField(controller:controller,onChanged:search,decoration:InputDecoration(hintText:'Search anime…',prefixIcon:const Icon(Icons.search,color:appPurple),filled:true,fillColor:appPanel,border:OutlineInputBorder(borderRadius:BorderRadius.circular(15),borderSide:BorderSide.none)))),if(loading)const LinearProgressIndicator(color:appPurple),if(note!=null)Text(note!,style:const TextStyle(color:appMuted)),Expanded(child:GridView.builder(padding:const EdgeInsets.all(14),gridDelegate:const SliverGridDelegateWithFixedCrossAxisCount(crossAxisCount:2,childAspectRatio:.62,crossAxisSpacing:12,mainAxisSpacing:12),itemCount:results.length,itemBuilder:(_,i)=>AnimePoster(anime:results[i],onTap:()=>widget.onOpen(results[i]))))]));}
